<script setup>
import {ref} from 'vue';import Dialog from './Dialog.vue';import StatusBadge from './StatusBadge.vue';import Icon from './Icon.vue';import {dateLabel,money} from '../utils/shipments.js';
defineProps({shipment:Object});const emit=defineEmits(['close','edit','delete']);const confirming=ref(false);
</script>
<template><Dialog :title="shipment.id" @close="emit('close')"><div class="detail-top"><StatusBadge :status="shipment.status"/><span class="muted">{{shipment.mode}} freight</span></div><div class="detail-route"><div><small>ORIGIN</small><h3>{{shipment.origin}}</h3><span>{{shipment.originCountry||'—'}}</span></div><Icon name="ArrowRight" :size="26"/><div><small>DESTINATION</small><h3>{{shipment.destination}}</h3><span>{{shipment.destinationCountry||'—'}}</span></div></div><dl class="detail-grid"><div><dt>Customer</dt><dd>{{shipment.customer}}</dd></div><div><dt>Expected arrival</dt><dd>{{dateLabel(shipment.eta)}}</dd></div><div><dt>Weight</dt><dd>{{shipment.weight.toLocaleString()}} kg</dd></div><div><dt>Shipment value</dt><dd>{{money(shipment.value)}}</dd></div><div><dt>Reference</dt><dd>{{shipment.reference||'—'}}</dd></div><div><dt>Created</dt><dd>{{dateLabel(shipment.created)}}</dd></div></dl><p class="goods">{{shipment.description}}</p><h3 class="subheading">Shipment timeline</h3><ol class="timeline"><li v-for="(event,i) in shipment.history" :key="i"><i></i><div><b>{{event.status}}</b><span>{{dateLabel(event.date)}}</span><p>{{event.note}}</p></div></li></ol><div v-if="confirming" class="delete-confirm" role="alert"><p>Delete {{shipment.id}}? This removes it from your local workspace.</p><button class="btn danger" @click="emit('delete',shipment.id)">Delete shipment</button><button class="btn" @click="confirming=false">Keep shipment</button></div><div v-else class="dialog-actions"><button class="btn danger-ghost" @click="confirming=true"><Icon name="Trash2"/>Delete</button><button class="btn primary" @click="emit('edit',shipment)"><Icon name="Pencil"/>Edit shipment</button></div></Dialog></template>
